# Main UI for Significance Analysis Results Tab

#' Create the UI for a single significance analysis results tab
#'
#' This function creates a complete tabPanel containing both the results
#' table and volcano plots for a single contrast comparison.
#'
#' @param ids List of IDs generated by create_contrast_ids()
#' @param title Tab title displayed to user
#' @param value Tab value for programmatic access
#' @param contrast Character vector c(group1, group2)
#' @return tabPanel UI object ready to be added with appendTab()
#' @export
#' @examples
#' ns <- NS("sig_analysis")
#' ids <- create_contrast_ids(ns, c("Treatment", "Control"))
#' tab <- results_tab_ui(
#'   ids = ids,
#'   title = "Treatment vs Control",
#'   value = "Treatment_Control",
#'   contrast = c("Treatment", "Control")
#' )
results_tab_ui <- function(ids, title, value, contrast) {
  tabPanel(
    title = title,
    value = value,
    tabsetPanel(
      # Table tab
      create_table_tab_ui(ids, contrast),

      # Volcano tab
      create_volcano_tab_ui(ids, contrast)
    )
  )
}
